const a = $input.all()[0].json.body.data;
const dtStart = new Date(a.startTime || a.start || a.scheduledAt);
const dtEnd = new Date(a.endTime || a.end || new Date(dtStart.getTime() + 60 * 60 * 1000).toISOString());
// Format dates for ICS: YYYYMMDDTHHMMSSZ
const fmtICS = (d) => d.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
const uid = `${a.id}@dayjoy.in`;
const dtstamp = fmtICS(new Date());
const location = a.type === 'ONLINE' ? (a.meetingLink || 'https://meet.dayjoy.in/' + a.id) : (a.location || '');
const attendees = [
  a.customerEmail ? `ATTENDEE;CN=${a.customerName || 'Customer'};RSVP=TRUE:mailto:${a.customerEmail}` : '',
  a.employeeEmail ? `ATTENDEE;CN=${a.employeeName || 'Employee'};RSVP=TRUE:mailto:${a.employeeEmail}` : ''
].filter(Boolean).join('\r\n');
const ics = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//Dayjoy//Appointment//EN',
  'METHOD:REQUEST',
  'BEGIN:VEVENT',
  `UID:${uid}`,
  `DTSTAMP:${dtstamp}`,
  `DTSTART:${fmtICS(dtStart)}`,
  `DTEND:${fmtICS(dtEnd)}`,
  `SUMMARY:${a.title || 'Dayjoy Appointment'}`,
  `DESCRIPTION:${(a.agenda || a.notes || '').replace(/\n/g, '\\n')}`,
  `LOCATION:${location}`,
  attendees,
  'ORGANIZER;CN=Dayjoy:mailto:appointments@dayjoy.in',
  'STATUS:CONFIRMED',
  'BEGIN:VALARM',
  'TRIGGER:-PT1H',
  'ACTION:DISPLAY',
  'DESCRIPTION:Appointment in 1 hour',
  'END:VALARM',
  'END:VEVENT',
  'END:VCALENDAR'
].filter(Boolean).join('\r\n');
const fmtDisplay = (d) => d.toLocaleString('en-IN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Kolkata' });
const html = `
<!doctype html><html><body style="font-family:Arial,Helvetica,sans-serif;color:#1f2937;background:#fff7ed;margin:0;padding:0;">
  <div style="max-width:560px;margin:0 auto;padding:32px;">
    <h1 style="color:#ea580c;">✅ Appointment Confirmed</h1>
    <p>Hi ${a.customerName || 'Customer'},</p>
    <p>Your appointment has been confirmed. We've attached a calendar invite (.ics) — open it to add this event to your calendar.</p>
    <table style="width:100%;border-collapse:collapse;margin:16px 0;">
      <tr><td style="padding:8px;background:#ffedd5;"><strong>When:</strong></td><td style="padding:8px;background:#fff;">${fmtDisplay(dtStart)} – ${fmtDisplay(dtEnd)}</td></tr>
      <tr><td style="padding:8px;background:#ffedd5;"><strong>With:</strong></td><td style="padding:8px;background:#fff;">${a.employeeName || 'Dayjoy Team'}</td></tr>
      <tr><td style="padding:8px;background:#ffedd5;"><strong>Location:</strong></td><td style="padding:8px;background:#fff;">${location || 'To be confirmed'}</td></tr>
    </table>
    ${a.type === 'ONLINE' && a.meetingLink ? `<p><a href="${a.meetingLink}" style="background:#ea580c;color:#fff;padding:10px 18px;border-radius:6px;text-decoration:none;display:inline-block;">Join Meeting →</a></p>` : ''}
    <p style="background:#fef3c7;border-left:4px solid #f59e0b;padding:12px;font-size:14px;">📅 Open the attached <strong>invite.ics</strong> file to add this to your Google/Outlook/Apple calendar.</p>
    <hr style="margin:24px 0;border:none;border-top:1px solid #fed7aa;" />
    <p style="font-size:12px;color:#6b7280;">Dayjoy Wellness Pvt. Ltd. · appointments@dayjoy.in</p>
  </div>
</body></html>`;
return [{
  json: {
    html,
    ics,
    icsFilename: `dayjoy-appointment-${a.id}.ics`,
    subject: `Appointment Confirmed: ${a.title || 'Dayjoy Appointment'}`,
    customerEmail: a.customerEmail,
    appointmentId: a.id,
    tenantId: a.tenantId
  }
}];
